 const push=(el,extra)=>{if(!vis(el))return;const r=R(el);if(r[2]>=vw-1&&r[3]>=vh-1)return;comps.push([nm(el)+(extra||''),r,(el.textContent||'').trim().replace(/\s+/g,' ').slice(0,34)]);};
 const hud=document.getElementById('hud');
 if(hud){for(const el of hud.children)push(el);
   for(const el of hud.querySelectorAll('*'))if(/boss/i.test(el.id||'')||/boss/i.test(typeof el.className==='string'?el.className:''))push(el,'|BOSS');}
 for(const el of document.querySelectorAll('body *')){const id=el.id||'';const cl=typeof el.className==='string'?el.className:'';
   if(/boss/i.test(id)||/boss/i.test(cl)){if(!comps.some(c=>c[0].split('|')[0]===nm(el)))push(el,'|BOSS');}}
 const rs=document.getElementById('run-screen');
 if(rs&&vis(rs)){for(const el of rs.querySelectorAll('.rn-page,.rn-card,.rn-door,button'))push(el);}
 for(const el of document.querySelectorAll('body > *'))if(el.tagName!=='CANVAS'&&el.id!=='hud'&&el.id!=='run-screen')push(el);
 const over=[];
 for(const el of document.querySelectorAll('body *')){if(el.tagName==='CANVAS'||el.ownerSVGElement)continue;if(!vis(el))continue;const r=el.getBoundingClientRect();
  if(r.left<-0.5||r.top<-0.5||r.right>vw+0.5||r.bottom>vh+0.5){if(Math.round(r.width)>=vw&&Math.round(r.height)>=vh)continue;over.push([nm(el),R(el)]);}}
 const outv=comps.filter(c=>c[1][0]<-0.5||c[1][1]<-0.5||c[1][0]+c[1][2]>vw+0.5||c[1][1]+c[1][3]>vh+0.5).map(c=>[c[0],c[1]]);
 const ix=(a,b)=>{const x=Math.min(a[0]+a[2],b[0]+b[2])-Math.max(a[0],b[0]);const y=Math.min(a[1]+a[3],b[1]+b[3])-Math.max(a[1],b[1]);return x>0.5&&y>0.5?[Math.round(x),Math.round(y)]:null;};
 const contains=(a,b)=>a[0]<=b[0]+0.5&&a[1]<=b[1]+0.5&&a[0]+a[2]>=b[0]+b[2]-0.5&&a[1]+a[3]>=b[1]+b[3]-0.5;
 const hits=[];
 for(let i=0;i<comps.length;i++)for(let j=i+1;j<comps.length;j++){const A=comps[i],B=comps[j];
   if(A[0].split('|')[0]===B[0].split('|')[0])continue;
   const o=ix(A[1],B[1]);if(!o)continue;
   const rel=contains(A[1],B[1])?'A_contains_B':(contains(B[1],A[1])?'B_contains_A':'CROSS');
   hits.push([A[0],A[1],B[0],B[1],o,rel]);}
 let bn=null;try{bn=E.hud.banner();}catch(e){}
 let bp=null;try{const r=E.cmd("runState");bp=r&&r.boss?{pct:r.boss.pct,hp:r.boss.hp,adds:r.boss.adds,phases:r.boss.phasesFired,quake:!!r.boss.quake}:null;}catch(e){}
 let sc='?',us='?';try{sc=E.state().scene;}catch(e){}try{us=E.runUi().screen;}catch(e){}
 return {t:+performance.now().toFixed(0),tick:E.tick,vp:[vw,vh],scene:sc,uiScreen:us,banner:bn,boss:bp,enemies:(()=>{try{return E.state().enemies.length}catch(e){return -1}})(),comps,overflow:over,outOfViewport:outv,overlaps:hits};};
const t0=performance.now();const seen=new Map();const incidents=[];const all=[];
while(performance.now()-t0<14000){const g=grab();all.push(g);
 const sig=JSON.stringify(g.comps.map(c=>[c[0],c[1]]));
 if(!seen.has(sig))seen.set(sig,g);
 if(g.overlaps.some(h=>h[5]==='CROSS')||g.outOfViewport.length||g.overflow.length)incidents.push(g);
 await new Promise(r=>setTimeout(r,250));}
const isBoss=(c)=>/\|BOSS$/.test(c[0]);
const isBanner=(c)=>/hud-banner/.test(c[0])&&/show/.test(c[0]);
const bossFrames=all.filter(g=>g.comps.some(isBoss));
const bannerFrames=all.filter(g=>g.comps.some(isBanner));
const both=all.filter(g=>g.comps.some(isBoss)&&g.comps.some(isBanner));
return {tag:TAG,samples:all.length,distinctLayouts:seen.size,
 bossPlateFrames:bossFrames.length,bannerFrames:bannerFrames.length,bossPlateAndBannerFrames:both.length,
 crossOverlapIncidents:incidents.filter(g=>g.overlaps.some(h=>h[5]==='CROSS')).length,
 outOfViewportIncidents:incidents.filter(g=>g.outOfViewport.length).length,
 overflowIncidents:incidents.filter(g=>g.overflow.length).length,
 firstBossFrame:bossFrames[0]||null,lastBossFrame:bossFrames[bossFrames.length-1]||null,
 bothFrame:both[0]||null,bothFrameLast:both[both.length-1]||null,
 incidentSample:incidents.slice(0,4),
 layouts:[...seen.values()].slice(0,10)};})()
